/// <summary>
/// class <c>METTelemetryTransferOrderReceiptInfoEvent</c> is used to log error event whenever transfer order info event.
/// </summary>
internal final class METTelemetryTransferOrderReceiptInfoEvent extends ISMTelemetryBase
{
}

Method.Source:
/// <summary>
/// Initialize the class <c>METTelemetryTransferOrderReceiptInfoEvent</c>
/// </summary>
/// <returns> Instance of class <c>METTelemetryTransferOrderReceiptInfoEvent</c> </returns>
public static METTelemetryTransferOrderReceiptInfoEvent construct()
{
    return new METTelemetryTransferOrderReceiptInfoEvent();
}

/// <summary>
/// Run transfer order telmetry log
/// </summary>
/// <param name = "_InventTransferTable"> table <c>_InventTransferTable</c> </param>
public static void runTelemetryEvent(InventTransferTable _InventTransferTable)
{
    METTelemetryTransferOrderReceiptInfoEvent transferOrderReceiptEvent = METTelemetryTransferOrderReceiptInfoEvent::construct();

    transferOrderReceiptEvent.addRunTimePropertyToAppinsights(_InventTransferTable);

    transferOrderReceiptEvent.processEvent(METTelemetryEventNames::TOReceiptInfoEvent);
}

/// <summary>
/// if the log level is set to information it will log the request and response data as wekk as there is an error
/// </summary>
/// <returns> a boolean value </returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// Add runtime telemetry property to application insights.
/// </summary>
/// <param name = "_InventTransferTable"> table <c>InventTransferTable</c> </param>
public void addRunTimePropertyToAppinsights(InventTransferTable _inventTransferTable)
{
    METInventTransferTableExt inventTransferTableExt = METInventTransferTableExt::findByTransferId(_inventTransferTable.TransferId);

    this.addRuntimeProperty('TransferId', _inventTransferTable.TransferId);
    this.addRuntimeProperty('FromWarehouseId' ,_inventTransferTable.InventLocationIdFrom);
    this.addRuntimeProperty('ToWarehouseId', _inventTransferTable.InventLocationIdTo);
    this.addRuntimeProperty('TransferType', enum2Str(inventTransferTableExt.TransferType));
    this.addRuntimeProperty('OrderSplitGroup', inventTransferTableExt.OrderSplitGroup);
}
